extends Control

@onready var coins_label: Label = $MarginContainer/VBoxContainer/CoinsLabel
@onready var click_button: Button = $MarginContainer/VBoxContainer/ClickUpgradeButton
@onready var auto_button: Button = $MarginContainer/VBoxContainer/AutoUpgradeButton

const CLICK_PRICE := 25
const AUTO_PRICE := 100

func _ready() -> void:
	update_ui()

func update_ui() -> void:
	coins_label.text = "Монеты: " + str(Global.coins)
	click_button.text = "Усилить клик (+1) — " + str(CLICK_PRICE)
	auto_button.text = "Доход +1/сек — " + str(AUTO_PRICE)

func _on_click_upgrade_button_pressed() -> void:
	if Global.spend_coins(CLICK_PRICE):
		Global.coins_per_click += 1
		update_ui()

func _on_auto_upgrade_button_pressed() -> void:
	if Global.spend_coins(AUTO_PRICE):
		Global.coins_per_second += 1
		update_ui()

func _on_back_button_pressed() -> void:
	get_tree().change_scene_to_file("res://scenes/main.tscn")

func save_game() -> void:
	var data := {
		"coins": coins,
		"coins_per_click": coins_per_click,
		"coins_per_second": coins_per_second,
		"purchased_upgrades": purchased_upgrades
	}
	var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file == null:
		push_error("Не удалось открыть файл сохранения для записи")
		return
	file.store_string(JSON.stringify(data))

func load_game() -> void:
	if not FileAccess.file_exists(SAVE_PATH):
		return
	var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file == null:
		return
	var parsed: Variant = JSON.parse_string(file.get_as_text())
	if typeof(parsed) != TYPE_DICTIONARY:
		push_warning("Файл сохранения имеет неверный формат")
		return
	coins = int(parsed.get("coins", 0))
	coins_per_click = int(parsed.get("coins_per_click", 1))
	coins_per_second = int(parsed.get("coins_per_second", 0))
	var raw_upgrades: Variant = parsed.get("purchased_upgrades", [])
	purchased_upgrades.clear()
	for upgrade in raw_upgrades:
		purchased_upgrades.append(str(upgrade))
